def api_call(func=None, errors=Exception, into=None, default=None):
    """Calls func and handles errors using reraise semantics.

    If into is callable, it's called with the exception to create a new one.
    If into is an exception class, the original is raised as that type.
    Returns default on error if specified.

    Can be used as @api_call or api_call(func, errors=..., into=...).
    """
    def wrapper(f):
        def inner(*args, **kwargs):
            try:
                return f(*args, **kwargs)
            except errors as e:
                if callable(into):
                    raise into(e)
                elif into is not None:
                    # Re-raise as different type
                    raise_from(into, e)
                elif default is not None:
                    return default
                else:
                    raise
        return wraps(f)(inner)

    if func is not None and callable(func):
        return wrapper(func)
    return wrapper

